package com.komainos.mantenimiento.service;
import com.komainos.catalogo.model.*;import com.komainos.catalogo.repository.*;import com.komainos.catalogo.service.ServicioCatalogoAutomatizacion;import com.komainos.inventario.model.*;import com.komainos.inventario.repository.*;import com.komainos.inventario.service.ServicioCatalogos;import com.komainos.mantenimiento.model.*;import com.komainos.mantenimiento.repository.ReglaPoliticaCambioRepositorio;import com.komainos.shared.model.Actor;import com.komainos.shared.util.Tiempo;import com.komainos.auditoria.service.ServicioAuditoria;import com.komainos.auditoria.service.ServicioAuditoria.Operacion;
import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.data.domain.PageRequest;import java.util.*;import java.time.Clock;import java.math.BigDecimal;
@Service @RequiredArgsConstructor
public class ServicioDemostracionAutomatizacion {
 private final ScriptRepositorio scripts;private final ImplementacionScriptRepositorio implementaciones;private final MetricaRepositorio metricas;private final UmbralRepositorio umbrales;private final TareaRepositorio tareas;private final ServicioCatalogos catalogos;private final ServicioCatalogoAutomatizacion catalogo;private final ReglaPoliticaCambioRepositorio reglas;private final ServicioPoliticasCambio politicas;private final ServicioAuditoria auditoria;private final Clock reloj;
 /** Datos opcionales e idempotentes: nunca se reemplaza una configuración existente. */
 @Transactional public Map<String,Integer> cargar(Actor actor){
  scripts.bloquearCatalogo();Map<String,Metrica> conocidas=new HashMap<>();metricas.findAllByOrderByNombreAsc().forEach(m->conocidas.put(m.getCodigo(),m));Map<String,Integer> ids=new HashMap<>();
  for(String codigo:List.of("cpu_uso_pct","memoria_uso_pct","disco_uso_pct")){var m=conocidas.get(codigo);if(m==null){m=Metrica.nueva(codigo,codigo.equals("cpu_uso_pct")?"Uso de CPU":codigo.equals("memoria_uso_pct")?"Uso de memoria":"Uso de disco","%",TipoDato.DECIMAL,false);metricas.save(m);}
   String nombre="Demostración · "+m.getNombre();Integer idM=m.getId();var u=umbrales.findTodos().stream().filter(x->x.getMetrica().getId().equals(idM)&&x.getNombre().equals(nombre)).findFirst().orElse(null);if(u==null){u=Umbral.numerico(m,nombre,new Umbral.LimitesNumericos(OperadorComparacion.MAYOR_IGUAL,new BigDecimal("80"),new BigDecimal("95")),Tiempo.ahora(reloj));umbrales.save(u);}ids.put(codigo,u.getId());
  }
  Map<String,Script> porNombre=new HashMap<>();scripts.findAll().forEach(s->porNombre.put(s.getNombre(),s));
  for(String nombre:List.of("Análisis básico de salud","Comprobar capacidad de disco","Comprobar memoria disponible"))if(!porNombre.containsKey(nombre))porNombre.put(nombre,catalogo.guardarScript(null,nombre,nombre.startsWith("Análisis")?TipoScript.ANALISIS:TipoScript.MANTENIMIENTO,"Ejemplo para pruebas locales; revisar y aprobar antes de uso real",true,actor));
  for(var so:catalogos.listarSistemasOperativos())if(so.isActivo())for(var version:so.getVersiones())if(version.isActivo())for(var script:porNombre.values())if(List.of("Análisis básico de salud","Comprobar capacidad de disco","Comprobar memoria disponible").contains(script.getNombre())){
   if(script.getTipo()==TipoScript.ANALISIS&&implementaciones.findByVersionSistemaOperativoId(version.getId()).stream().anyMatch(i->i.getScript().isActivo()&&i.getScript().getTipo()==TipoScript.ANALISIS&&i.ultimaHabilitada().isPresent()))continue;
   var existente=implementaciones.findByVersionSistemaOperativoId(version.getId()).stream().filter(i->i.getScript().getId().equals(script.getId())).findFirst();var impl=existente.orElseGet(()->catalogo.implementar(script.getId(),version.getId(),actor));if(impl.ultimaHabilitada().isEmpty()){
    String recurso=(script.getTipo()==TipoScript.ANALISIS?"analisis":script.getNombre().contains("disco")?"comprobar_disco":"comprobar_memoria")+(so.getFamilia()==FamiliaSistemaOperativo.WINDOWS?"_windows.ps1":"_linux.sh");catalogo.publicar(impl.getId(),recurso(recurso),"Versión de demostración inicial",List.of(),actor);
   }
  }
  for(String codigo:List.of("disco_uso_pct","memoria_uso_pct")){String nombre=codigo.startsWith("disco")?"Comprobar capacidad de disco":"Comprobar memoria disponible";if(tareas.findAll().stream().noneMatch(t->t.getNombre().equals(nombre)))catalogo.guardarTarea(null,new ServicioCatalogoAutomatizacion.DatosTarea(porNombre.get(nombre).getId(),nombre,"Control de diagnóstico no destructivo",NivelAfectacion.SIN_AFECTACION,codigo.startsWith("disco")?10:20,5,true,Set.of(ids.get(codigo))),actor);}
  for(var entorno:catalogos.listarEntornos())if(entorno.isActivo())for(var nivel:NivelAfectacion.values())if(reglas.findByEntornoIdAndAfectacion(entorno.getId(),nivel).isEmpty())politicas.guardar(null,new ServicioPoliticasCambio.DatosRegla(entorno.getId(),nivel,nivel!=NivelAfectacion.SIN_AFECTACION,nivel!=NivelAfectacion.SIN_AFECTACION,true,Set.of(TipoDestinatario.ADMINISTRADOR,TipoDestinatario.RESPONSABLE),null),actor);
  auditoria.registrar(actor,Operacion.de("CARGAR_DEMOSTRACION_AUTOMATIZACION","automatizacion",null));return Map.of("scripts",3,"metricas",3,"tareas",2);
 }
 private String recurso(String nombre){try(var in=getClass().getResourceAsStream("/ansible/scripts/"+nombre)){if(in==null)throw new IllegalStateException("Falta el script de demostración");return new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);}catch(java.io.IOException e){throw new IllegalStateException("No se pudo leer el script de demostración",e);}}
}
